import {ensureInstallation,routeSpecs,routeRecord,routeGeometry,routeAnchor,assignCable,routeIssues,deleteRoute} from './installation-model.mjs?v=0.19.0';

let api,selected='',pivotIndex=-1,drag=null;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toFixed(2);
function specs(p){const list=routeSpecs(p);if(!list.some(s=>s.id===selected))selected=list[0]?.id||'';return list;}
function handleParts(value){const i=value.lastIndexOf(':');return [value.slice(0,i),value.slice(i+1)];}
function xy(ev,svg){const pt=svg.createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;const q=pt.matrixTransform(svg.getScreenCTM().inverse());return {x:q.x/100,y:q.y/100};}
const path=points=>points.map((q,i)=>(i?'L':'M')+`${q.x*100},${q.y*100}`).join(' ');
const visible=(p,s)=>p.installation.filters[s.kind]!==false;
export function routeLayer(p){ensureInstallation(p);return specs(p).filter(s=>visible(p,s)).map(s=>{const g=routeGeometry(p,s);if(!g)return '';const r=routeRecord(p,s.id),colour=r.cableSnapshot?.color||({data:'#458db9',power:'#d18c43',inject:'#bb6d4b',other:'#8a729a'})[s.kind],d=path(g.points),state=routeIssues(p,s),short=state.state==='short',issues=state.issues,chosen=s.id===selected,handles=chosen?[g.points[0],...r.points,g.points.at(-1)]:[];return `<g class="physical-route ${s.kind} ${chosen?'selected':''} ${issues.length?'has-issues':state.state==='unknown'?'unknown':'valid'}" data-route="${E(s.id)}"><title>${E(s.name)}: ${issues.length?issues.join("; "):state.state==="unknown"?"Physical cable length unknown":"Cable length valid"}</title><path class="route-hit" d="${d}" data-route-path="${E(s.id)}"/><path class="route-line" d="${d}" stroke="${colour}" data-route-path="${E(s.id)}"/>${issues.length?`<text class="route-alert" x="${g.points.at(-1).x*100+8}" y="${g.points.at(-1).y*100-8}">!<title>${E(issues.join('; '))}</title></text>`:''}${p.installation.animate?`<circle r="4" fill="${colour}" class="route-pulse"><animateMotion dur="4s" repeatCount="indefinite" path="${d}"/></circle>`:''}${handles.map((q,i)=>i===0||i===handles.length-1?`<circle class="route-handle endpoint" data-route-endpoint="${E(s.id)}:${i===0?'start':'end'}" cx="${q.x*100}" cy="${q.y*100}" r="7" tabindex="0" role="button" aria-label="Move ${i===0?'start':'end'} of ${E(s.name)}"/>`:`<circle class="route-handle pivot ${i-1===pivotIndex?'active':''}" data-route-pivot="${E(s.id)}:${i-1}" cx="${q.x*100}" cy="${q.y*100}" r="7" tabindex="0" role="button" aria-label="Move pivot ${i} of ${E(s.name)}"/>`).join('')}</g>`;}).join('');}
export function routeControls(p){ensureInstallation(p);const f=p.installation.filters;return `<div class="route-filter">${[['data','Data'],['power','Power'],['inject','Injection'],['other','Other']].map(([k,t])=>`<button type="button" data-route-action="filter:${k}" class="${f[k]!==false?'active':''}" aria-pressed="${f[k]!==false}">${t}</button>`).join('')}<button type="button" data-route-action="auto-route" class="${p.installation.autoRoute?'active':''}" aria-pressed="${p.installation.autoRoute}">${p.installation.autoRoute?'Auto route on':'Auto route off'}</button><button type="button" data-route-action="labels" class="${p.installation.showLabels?'active':''}" aria-pressed="${p.installation.showLabels}">${p.installation.showLabels?'Labels on':'Labels off'}</button><button type="button" data-route-action="animate" class="${p.installation.animate?'active':''}" aria-pressed="${p.installation.animate}">${p.installation.animate?'Flow on':'Flow off'}</button></div>`;}
export function routeInspector(p,lib){ensureInstallation(p);const all=specs(p),s=all.find(x=>x.id===selected);if(!s)return '<p class="micro">Add hardware or pixels to make a cable route.</p>';const g=routeGeometry(p,s),r=routeRecord(p,s.id),standards=lib.cables||[],ref=r.cableRef?.id||'',snap=r.cableSnapshot,chosen=standards.some(c=>c.id===ref);return `<div class="route-inspector"><div class="section-label">PHYSICAL CABLE ROUTE</div><label>Connection<select data-route-field="select">${all.map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.name)} · ${E(x.kind)}</option>`).join('')}</select></label><p class="micro">${E(s.from)} → ${E(s.to)}${s.port?' · '+E(s.port):''}. Double-click a route to add a pivot, or use Add pivot. Drag endpoints and pivots.</p><div class="route-metrics"><span>Routed distance <strong id="route-length-live">${g?fmt(g.routeM):'—'} m</strong></span><span>Slack allowance <strong>${g?fmt(g.allowanceM):'—'} m</strong></span><span>Required cable <strong>${g?fmt(g.requiredM):'—'} m</strong></span></div><div class="route-actions"><button type="button" class="btn" data-route-action="add-pivot">+ Add pivot</button>${pivotIndex>=0?`<button type="button" class="text-btn danger" data-route-action="delete-pivot">Delete pivot ${pivotIndex+1}</button>`:''}</div><label>Physical cable standard<select data-route-field="standard"><option value="">None / custom length</option>${!chosen&&snap?`<option value="${E(ref)}" selected>${E(snap.name)} · archived v${snap.version}</option>`:''}${standards.map(c=>`<option value="${E(c.id)}" ${c.id===ref?'selected':''}>${E(c.name)} · ${c.lengthM} m</option>`).join('')}</select></label>${snap?`<p class="micro">Using ${E(snap.name)} v${snap.version} · ${snap.lengthM} m · ${snap.pins} pins${chosen&&standards.find(c=>c.id===ref).version>snap.version?' · newer standard available':''}.</p>${chosen&&standards.find(c=>c.id===ref).version>snap.version?`<button class="text-btn" data-route-action="update-standard">Update this cable to latest</button>`:''}`:`<label>Physical cable length (m)<input type="number" min="0" max="10000" step="any" value="${r.physicalM??''}" placeholder="Not assigned" data-route-field="physical"></label>`}<div class="route-result ${g?.shortByM>0?'short':g?.spareM!=null?'spare':''}">${g?.shortByM>0?`⚠ Insufficient by ${fmt(g.shortByM)} m`:g?.spareM!=null?`${fmt(g.spareM)} m spare cable`:'Assign a cable to compare lengths'}</div>${routeIssues(p,s).issues.length?`<ul class="route-issues">${routeIssues(p,s).issues.map(w=>`<li>! ${E(w)}</li>`).join('')}</ul>`:''}${s.id.startsWith('custom:')||s.id.startsWith('inject:')?`<button type="button" class="text-btn danger" data-route-action="delete-route">Delete connection</button>`:''}<div class="section-label">PROJECT SERVICE ALLOWANCE</div><label>Slack mode<select data-route-field="slack-mode"><option value="off" ${p.installation.slack.mode==='off'?'selected':''}>Off</option><option value="percent" ${p.installation.slack.mode==='percent'?'selected':''}>Percentage</option><option value="fixed" ${p.installation.slack.mode==='fixed'?'selected':''}>Fixed metres</option></select></label>${p.installation.slack.mode!=='off'?`<label>${p.installation.slack.mode==='percent'?'Slack (%)':'Slack (m)'}<input type="number" min="0" max="1000" step="any" data-route-field="slack-value" value="${p.installation.slack.value}"></label>`:''}<p class="micro">Slack is off unless enabled. It adds to the required cable length; the geometric route remains separate.</p></div>`;}
function refresh(){const layer=document.querySelector('#room-routes');if(!layer)return;const p=api.getProject();layer.innerHTML=routeLayer(p);const s=specs(p).find(x=>x.id===selected),g=s&&routeGeometry(p,s),read=document.querySelector('#route-length-live');if(read&&g)read.textContent=fmt(g.routeM)+' m';}
function refreshDrag(){const p=api.getProject(),s=specs(p).find(x=>x.id===drag.id),g=s&&routeGeometry(p,s),group=document.querySelector(`[data-route="${CSS.escape(drag.id)}"]`);if(!g||!group)return;const d=path(g.points);group.querySelectorAll('[data-route-path]').forEach(el=>el.setAttribute('d',d));group.querySelector('animateMotion')?.setAttribute('path',d);group.querySelectorAll('[data-route-pivot]').forEach((el,i)=>{const q=routeRecord(p,drag.id).points[i];el.setAttribute('cx',q.x*100);el.setAttribute('cy',q.y*100);});for(const end of ['start','end']){const q=g.points[end==='start'?0:g.points.length-1],el=group.querySelector(`[data-route-endpoint$=":${end}"]`);el?.setAttribute('cx',q.x*100);el?.setAttribute('cy',q.y*100);}const read=document.querySelector('#route-length-live');if(read)read.textContent=fmt(g.routeM)+' m';}
function nearestIndex(points,q){let best=0,min=Infinity;for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1],dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((q.x-a.x)*dx+(q.y-a.y)*dy)/(dx*dx+dy*dy||1))),d=(q.x-a.x-t*dx)**2+(q.y-a.y-t*dy)**2;if(d<min){min=d;best=i;}}return best;}
export function installRoutes(a){api=a;document.addEventListener('click',e=>{const pathEl=e.target.closest('[data-route-path]');if(pathEl){selected=pathEl.dataset.routePath;pivotIndex=-1;api.render();return;}const pv=e.target.closest('[data-route-pivot]');if(pv){const [id,i]=handleParts(pv.dataset.routePivot);selected=id;pivotIndex=+i;api.render();return;}const el=e.target.closest('[data-route-action]');if(!el)return;const [action,value]=el.dataset.routeAction.split(':'),p=api.getProject(),r=routeRecord(p,selected);if(action==='filter'){api.transact(()=>p.installation.filters[value]=p.installation.filters[value]===false);return;}if(action==='auto-route'){api.transact(()=>p.installation.autoRoute=!p.installation.autoRoute);return;}if(action==='labels'){api.transact(()=>p.installation.showLabels=!p.installation.showLabels);return;}if(action==='animate'){api.transact(()=>p.installation.animate=!p.installation.animate);return;}if(action==='add-pivot'){const s=specs(p).find(x=>x.id===selected),g=s&&routeGeometry(p,s);if(!g)return;let longest=-1,index=0;for(let i=0;i<g.points.length-1;i++){const d=Math.hypot(g.points[i+1].x-g.points[i].x,g.points[i+1].y-g.points[i].y);if(d>longest){longest=d;index=i;}}const a=g.points[index],b=g.points[index+1];api.transact(()=>{if(!r.points.length&&p.installation.autoRoute)r.points.push(...g.points.slice(1,-1));r.points.splice(index,0,{x:+((a.x+b.x)/2).toFixed(3),y:+((a.y+b.y)/2).toFixed(3)});pivotIndex=index;});return;}if(action==='delete-pivot'){api.transact(()=>{r.points.splice(pivotIndex,1);pivotIndex=-1;});return;}if(action==='delete-route'){api.transact(()=>deleteRoute(p,selected));selected='';pivotIndex=-1;return;}if(action==='update-standard'){const standard=api.getLibrary().cables.find(c=>c.id===r.cableRef?.id);if(standard)api.transact(()=>assignCable(p,selected,standard));return;}});
 document.addEventListener('dblclick',e=>{const el=e.target.closest('[data-route-path]');if(!el)return;const p=api.getProject(),s=specs(p).find(x=>x.id===el.dataset.routePath),svg=el.closest('#room-canvas'),q=xy(e,svg),g=routeGeometry(p,s);selected=s.id;api.transact(()=>{const r=routeRecord(p,s.id);if(!r.points.length&&p.installation.autoRoute)r.points.push(...g.points.slice(1,-1));const idx=nearestIndex([g.points[0],...r.points,g.points.at(-1)],q);r.points.splice(idx,0,{x:+q.x.toFixed(3),y:+q.y.toFixed(3)});pivotIndex=idx;});e.preventDefault();});
 document.addEventListener('change',e=>{const k=e.target.dataset.routeField;if(!k)return;const t=e.target;if(!t.checkValidity()){t.reportValidity();return;}const p=api.getProject();if(k==='select'){selected=t.value;pivotIndex=-1;api.render();return;}api.transact(()=>{const r=routeRecord(p,selected);if(k==='standard')assignCable(p,selected,api.getLibrary().cables.find(c=>c.id===t.value)||null);else if(k==='physical')r.physicalM=t.value===''?null:+t.value;else if(k==='slack-mode')p.installation.slack.mode=t.value;else if(k==='slack-value')p.installation.slack.value=+t.value;});});
 document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-route-pivot],[data-route-endpoint]');if(!el||e.button!==0)return;const [id,index]=handleParts(el.dataset.routePivot||el.dataset.routeEndpoint),p=api.getProject(),r=routeRecord(p,id);selected=id;pivotIndex=el.dataset.routePivot?+index:-1;drag={id,index,kind:el.dataset.routePivot?'pivot':'endpoint',pointer:e.pointerId,before:structuredClone(r),svg:el.closest('#room-canvas')};el.setPointerCapture(e.pointerId);e.preventDefault();e.stopPropagation();});
 document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;const p=api.getProject(),r=routeRecord(p,drag.id),q=xy(e,drag.svg),snap=p.scene.snap;if(snap){q.x=Math.round(q.x/snap)*snap;q.y=Math.round(q.y/snap)*snap;}q.x=Math.max(0,Math.min(p.scene.width,q.x));q.y=Math.max(0,Math.min(p.scene.depth,q.y));if(drag.kind==='pivot')r.points[+drag.index]={x:+q.x.toFixed(3),y:+q.y.toFixed(3)};else {const s=specs(p).find(x=>x.id===drag.id),node=routeAnchor(p,s,drag.index),offset=drag.index==='start'?r.startOffset:r.endOffset;offset.x=+(q.x-node.x).toFixed(3);offset.y=+(q.y-node.y).toFixed(3);}refreshDrag();});
 document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.pointer)return;if(e.type==='pointercancel')Object.assign(routeRecord(api.getProject(),drag.id),drag.before);drag=null;api.save();api.render();});document.addEventListener('pointercancel',e=>{if(drag&&e.pointerId===drag.pointer){Object.assign(routeRecord(api.getProject(),drag.id),drag.before);drag=null;api.render();}});document.addEventListener('keydown',e=>{if(e.key==='Delete'&&e.target.matches('[data-route-pivot]')&&pivotIndex>=0){api.transact(()=>{routeRecord(api.getProject(),selected).points.splice(pivotIndex,1);pivotIndex=-1;});}});}
export function refreshRoutes(){refresh();}
